select * from class_session 
where schedule_no = #{scheduleNo}
AND TRUNC(CAST(session_start AS DATE)) = TRUNC(CAST(#{sessionStart} AS DATE))

mapper.update:
update class_session
set session_status = #{sessionStatus}
where session_no = #{sessionNo}

mapper.select:
	select count(*)
	from class_session cs
	where cs.session_no != #{sessionNo}
	and	  cs.classroom_no = #{classroomNo}
	and cs.session_status != '취소'
    and cs.session_start < #{sessionEnd}
    and cs.session_end > #{sessionStart}

mapper.update:
	update class_session
	set session_status = #{sessionStatus}

            , classroom_no = #{classroomNo}


            , session_start = #{sessionStart}


            , session_end = #{sessionEnd}

	where session_no = #{sessionNo}

UPDATE class_session
SET session_status = '종료'
WHERE session_no = #{sessionNo}
